-- 0001_baseline (PostgreSQL): the schema a fresh AnixOps Control created before
-- the migration runner (go_dev 4eb87485, release 4.2.1): the tables and
-- indexes of the application models, the kernel models and the startup
-- schema steps, in the order that start created them, flux tables included
-- (they go with the forwarding cleanup). The kernel API views are not part
-- of it: packagestore creates them at every start.
--
-- Recorded once from that start on an empty database (legacy_oracle_test.go)
-- and never edited: every database records this file's checksum
-- (docs/reference/database-migrations.md).
CREATE TABLE "v4_forward_legacy_archive" ("id" bigserial,"path" varchar(1024) NOT NULL,"sha256" varchar(64) NOT NULL,"size_bytes" bigint,"schema" varchar(64) NOT NULL,"trigger" varchar(16) NOT NULL,"actor" varchar(255),"row_counts" text,"created_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v4_forward_legacy_node" ("id" bigserial,"node_id" bigint NOT NULL,"node_ref" varchar(64) NOT NULL,"node_name" varchar(255),"state" varchar(16) NOT NULL,"checks" text,"detail" text,"checked_at" timestamptz,"abandoned_at" timestamptz,"abandoned_by" varchar(255),"abandon_reason" text,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v4_forward_legacy_drop" ("id" bigserial,"archive_id" bigint,"archive_path" varchar(1024),"archive_sha256" varchar(64),"backup" text,"dropped" text,"already_missing" text,"actor" varchar(255),"created_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_plan" ("id" bigserial,"group_id" bigint,"transfer_enable" bigint,"speed_limit" bigint,"device_limit" bigint,"name" varchar(255),"content" text,"show" bigint DEFAULT 0,"sort" bigint,"renew" bigint DEFAULT 1,"reset_price" bigint,"reset_traffic_method" bigint,"capacity_limit" bigint,"month_price" bigint,"quarter_price" bigint,"half_year_price" bigint,"year_price" bigint,"two_year_price" bigint,"three_year_price" bigint,"onetime_price" bigint,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_user" ("id" bigserial,"invite_user_id" bigint,"telegram_id" bigint,"email" varchar(255),"password" varchar(255),"password_algo" varchar(20),"password_salt" varchar(20),"balance" bigint DEFAULT 0,"discount" bigint,"commission_type" bigint DEFAULT 0,"commission_rate" bigint,"commission_balance" bigint DEFAULT 0,"token" varchar(36),"uuid" varchar(36),"device_limit" bigint,"speed_limit" bigint,"flow_reset_time" bigint DEFAULT 0,"transfer_enable" bigint DEFAULT 0,"u" bigint DEFAULT 0,"d" bigint DEFAULT 0,"plan_id" bigint,"group_id" bigint,"expired_at" bigint,"banned" bigint DEFAULT 0,"remark_content" text,"is_admin" bigint DEFAULT 0,"is_staff" bigint DEFAULT 0,"last_login_at" bigint,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_user_plan" FOREIGN KEY ("plan_id") REFERENCES "v2_plan"("id"));
CREATE TABLE "v2_order" ("id" bigserial,"invite_user_id" bigint,"user_id" bigint,"plan_id" bigint,"coupon_id" bigint,"payment_id" bigint,"type" bigint,"period" varchar(20),"trade_no" varchar(36),"callback_no" varchar(255),"total_amount" bigint,"discount_amount" bigint,"surplus_amount" bigint,"refund_amount" bigint,"balance" bigint,"surplus_order" text,"status" bigint DEFAULT 0,"commission_status" bigint DEFAULT 0,"commission_balance" bigint DEFAULT 0,"paid_at" bigint,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_order_plan" FOREIGN KEY ("plan_id") REFERENCES "v2_plan"("id"),CONSTRAINT "fk_v2_order_user" FOREIGN KEY ("user_id") REFERENCES "v2_user"("id"));
CREATE TABLE "v2_payment" ("id" bigserial,"name" varchar(100),"icon" varchar(255),"method" varchar(20),"provider" varchar(50),"config" text,"notify" varchar(255),"sort" bigint DEFAULT 0,"enable" bigint DEFAULT 1,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_payment_log" ("id" bigserial,"order_id" bigint,"payment_id" bigint,"trade_no" varchar(64),"callback_no" varchar(255),"method" varchar(20),"provider" varchar(50),"amount" bigint,"currency" varchar(10),"status" bigint DEFAULT 0,"raw_data" text,"tx_hash" varchar(255),"wallet_address" varchar(255),"network" varchar(50),"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_server_vmess" ("id" bigserial,"group_id" varchar(255),"route_id" varchar(255),"parent_id" bigint,"tags" varchar(255),"name" varchar(255),"rate" decimal DEFAULT 1,"host" varchar(255),"port" bigint,"server_port" bigint,"tls" bigint DEFAULT 0,"tls_settings" text,"show" bigint DEFAULT 0,"sort" bigint,"last_check_at" bigint,"created_at" timestamptz,"updated_at" timestamptz,"network" varchar(20),"network_settings" text,PRIMARY KEY ("id"));
CREATE TABLE "v2_server_vless" ("id" bigserial,"group_id" varchar(255),"route_id" varchar(255),"parent_id" bigint,"tags" varchar(255),"name" varchar(255),"rate" decimal DEFAULT 1,"host" varchar(255),"port" bigint,"server_port" bigint,"tls" bigint DEFAULT 0,"tls_settings" text,"show" bigint DEFAULT 0,"sort" bigint,"last_check_at" bigint,"created_at" timestamptz,"updated_at" timestamptz,"network" varchar(20),"network_settings" text,"flow" varchar(50),"encryption" varchar(50),"encryption_settings" text,"reality_settings" text,PRIMARY KEY ("id"));
CREATE TABLE "v2_server_trojan" ("id" bigserial,"group_id" varchar(255),"route_id" varchar(255),"parent_id" bigint,"tags" varchar(255),"name" varchar(255),"rate" decimal DEFAULT 1,"host" varchar(255),"port" bigint,"server_port" bigint,"tls" bigint DEFAULT 0,"tls_settings" text,"show" bigint DEFAULT 0,"sort" bigint,"last_check_at" bigint,"created_at" timestamptz,"updated_at" timestamptz,"network" varchar(20),"network_settings" text,"server_name" varchar(255),"allow_insecure" bigint DEFAULT 0,PRIMARY KEY ("id"));
CREATE TABLE "v2_server_shadowsocks" ("id" bigserial,"group_id" varchar(255),"route_id" varchar(255),"parent_id" bigint,"tags" varchar(255),"name" varchar(255),"rate" decimal DEFAULT 1,"host" varchar(255),"port" bigint,"server_port" bigint,"tls" bigint DEFAULT 0,"tls_settings" text,"show" bigint DEFAULT 0,"sort" bigint,"last_check_at" bigint,"created_at" timestamptz,"updated_at" timestamptz,"cipher" varchar(50),"server_key" varchar(255),"obfs" varchar(20),"obfs_settings" text,PRIMARY KEY ("id"));
CREATE TABLE "v2_node" ("id" bigserial,"name" varchar(255),"host" varchar(255),"port" bigint DEFAULT 443,"api_key" varchar(64),"api_key_hash" varchar(64),"secret" varchar(255),"status" bigint DEFAULT 0,"tags" varchar(255),"group_id" bigint,"rate" decimal DEFAULT 1,"traffic_rate" decimal DEFAULT 1,"sort" bigint DEFAULT 0,"show" bigint DEFAULT 1,"auto_register" bigint DEFAULT 0,"parent_id" bigint,"node_group_id" bigint,"machine_fingerprint" varchar(64),"approval" varchar(16) NOT NULL DEFAULT 'approved',"last_public_address" varchar(64),"monthly_limit" bigint,"monthly_upload" bigint DEFAULT 0,"monthly_download" bigint DEFAULT 0,"monthly_reset_day" bigint DEFAULT 1,"raw_config" text,"server_ip" varchar(45),"server_version" varchar(50),"server_os" varchar(100),"cpu_usage" decimal DEFAULT 0,"memory_usage" decimal DEFAULT 0,"disk_usage" decimal DEFAULT 0,"uptime" bigint DEFAULT 0,"online_users" bigint DEFAULT 0,"runtime_healthy" boolean DEFAULT true,"runtime_error" text,"runtime_checked_at" bigint,"total_upload" bigint DEFAULT 0,"total_download" bigint DEFAULT 0,"last_check_at" bigint,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_node_protocol" ("id" bigserial,"node_id" bigint,"name" varchar(100),"type" varchar(20),"port" bigint,"enable" bigint DEFAULT 1,"show" bigint DEFAULT 1,"sort" bigint DEFAULT 0,"group_id" bigint,"host" varchar(255),"tls" bigint DEFAULT 0,"alpn" varchar(100),"settings" text,"tls_settings" text,"transport" varchar(20),"transport_settings" text,"reality_settings" text,"custom_config" text,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_node_protocols" FOREIGN KEY ("node_id") REFERENCES "v2_node"("id"));
CREATE TABLE "v2_subscription_group" ("id" bigserial,"name" varchar(100),"description" varchar(500),"priority" bigint DEFAULT 0,"enable" bigint DEFAULT 1,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_subscription_group_node_protocols" ("subscription_group_id" bigint,"node_protocol_id" bigint,PRIMARY KEY ("subscription_group_id","node_protocol_id"),CONSTRAINT "fk_v2_subscription_group_node_protocols_node_protocol" FOREIGN KEY ("node_protocol_id") REFERENCES "v2_node_protocol"("id"),CONSTRAINT "fk_v2_subscription_group_node_protocols_subscription_group" FOREIGN KEY ("subscription_group_id") REFERENCES "v2_subscription_group"("id"));
CREATE TABLE "v2_wireguard_peer" ("id" bigserial,"node_protocol_id" bigint,"user_id" bigint,"peer_ip" varchar(64),"private_key" varchar(64),"public_key" varchar(64),"preshared_key" varchar(64),"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_wireguard_peer_node_protocol" FOREIGN KEY ("node_protocol_id") REFERENCES "v2_node_protocol"("id"),CONSTRAINT "fk_v2_wireguard_peer_user" FOREIGN KEY ("user_id") REFERENCES "v2_user"("id"));
CREATE TABLE "v2_authorized_key" ("id" bigserial,"name" varchar(100),"key" varchar(64),"key_hash" varchar(64),"used" bigint DEFAULT 0,"expire_at" bigint,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_server_log" ("id" bigserial,"user_id" bigint,"server_id" bigint,"server_type" varchar(20),"u" bigint,"d" bigint,"rate" decimal DEFAULT 1,"log_at" bigint,"created_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_online_log" ("id" bigserial,"user_id" bigint,"server_id" bigint,"server_type" varchar(20),"method" varchar(20),"ip" varchar(45),"created_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_stat_user" ("id" bigserial,"user_id" bigint,"server_rate" decimal,"u" bigint,"d" bigint,"record_type" varchar(1),"record_at" bigint,PRIMARY KEY ("id"));
CREATE TABLE "v2_stat_server" ("id" bigserial,"server_id" bigint,"server_type" varchar(20),"u" bigint,"d" bigint,"record_type" varchar(1),"record_at" bigint,PRIMARY KEY ("id"));
CREATE TABLE "v2_node_log" ("id" bigserial,"node_id" bigint NOT NULL,"level" varchar(20) NOT NULL,"source" varchar(120),"message" text NOT NULL,"trace_id" varchar(120),"fields_json" text,"logged_at" timestamptz,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_subscription_template" ("id" bigserial,"group_id" bigint,"name" varchar(255),"type" varchar(30),"enable" bigint DEFAULT 1,"sort" bigint DEFAULT 0,"tags" varchar(255),"template_json" text,"server" varchar(255),"port" bigint,"server_name" varchar(255),"tls" bigint DEFAULT 0,"tls_fingerprint" varchar(50),"alpn" varchar(100),"reality_public_key" varchar(100),"reality_short_id" varchar(50),"reality_spider_x" varchar(255),"reality_dest" varchar(255),"transport" varchar(20) DEFAULT 'tcp',"transport_settings" text,"flow" varchar(50),"encryption" varchar(50),"encryption_settings" text,"ss_cipher" varchar(50),"ss_server_key" varchar(100),"protocol_settings" text,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_subscription_group_templates" FOREIGN KEY ("group_id") REFERENCES "v2_subscription_group"("id"));
CREATE TABLE "v2_user_subscription_group" ("id" bigserial,"user_id" bigint,"group_id" bigint,"expire_at" bigint,"transfer_enable" bigint,"next_renew_price" bigint,"created_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_user_subscription_group_group" FOREIGN KEY ("group_id") REFERENCES "v2_subscription_group"("id"),CONSTRAINT "fk_v2_user_subscription_group_user" FOREIGN KEY ("user_id") REFERENCES "v2_user"("id"));
CREATE TABLE "v2_plan_subscription_group" ("id" bigserial,"plan_id" bigint,"group_id" bigint,"created_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_plan_subscription_group_group" FOREIGN KEY ("group_id") REFERENCES "v2_subscription_group"("id"),CONSTRAINT "fk_v2_plan_subscription_group_plan" FOREIGN KEY ("plan_id") REFERENCES "v2_plan"("id"));
CREATE TABLE "v2_event" ("id" bigserial,"type" varchar(100),"payload" text,"status" varchar(20) DEFAULT 'pending',"created_at" timestamptz,"processed_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_ticket" ("id" bigserial,"user_id" bigint,"subject" varchar(255),"level" bigint DEFAULT 1,"status" bigint DEFAULT 0,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_ticket_user" FOREIGN KEY ("user_id") REFERENCES "v2_user"("id"));
CREATE TABLE "v2_ticket_message" ("id" bigserial,"ticket_id" bigint,"user_id" bigint,"message" text,"is_admin" bigint DEFAULT 0,"created_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_ticket_messages" FOREIGN KEY ("ticket_id") REFERENCES "v2_ticket"("id"));
CREATE TABLE "v2_coupon" ("id" bigserial,"code" varchar(32),"name" varchar(255),"type" bigint DEFAULT 1,"value" bigint,"limit_use" bigint,"limit_use_with" bigint,"limit_period" varchar(20),"use_count" bigint DEFAULT 0,"started_at" bigint,"ended_at" bigint,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_coupon_usage" ("id" bigserial,"coupon_id" bigint,"user_id" bigint,"order_id" bigint,"created_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_knowledge" ("id" bigserial,"category" varchar(64),"title" varchar(255),"body" text,"sort" bigint DEFAULT 0,"show" bigint DEFAULT 1,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_node" ("id" bigserial,"name" varchar(100) NOT NULL,"type" varchar(20) NOT NULL DEFAULT 'exit',"host" varchar(255) NOT NULL,"port" bigint NOT NULL,"api_port" bigint,"api_token" varchar(100),"metrics_port" bigint,"region" varchar(50),"isp" varchar(50),"datacenter" varchar(100),"bandwidth" bigint,"status" bigint DEFAULT 0,"last_check" timestamptz,"latency" bigint,"load" decimal,"uptime" decimal,"tags" text,"weight" bigint DEFAULT 1,"max_conn" bigint,"enabled" boolean DEFAULT true,"node_group_id" bigint,"machine_fingerprint" varchar(64),"approval" varchar(16) NOT NULL DEFAULT 'approved',"last_public_address" varchar(64),"total_upload" bigint,"total_download" bigint,"current_conn" bigint,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_rule" ("id" bigserial,"name" varchar(100) NOT NULL,"enabled" boolean DEFAULT true,"relay_node_id" bigint NOT NULL,"listen_port" bigint NOT NULL,"protocol" varchar(10) DEFAULT 'tcp',"exit_node_id" bigint NOT NULL,"target_host" varchar(255) NOT NULL,"target_port" bigint NOT NULL,"user_id" bigint,"user_group_id" bigint,"allowed_ips" varchar(1000),"speed_limit" bigint,"traffic_limit" bigint,"expire_time" timestamptz,"upload" bigint,"download" bigint,"connections" bigint,"total_conns" bigint,"remark" varchar(500),"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_forward_rule_exit_node" FOREIGN KEY ("exit_node_id") REFERENCES "v2_forward_node"("id"),CONSTRAINT "fk_v2_forward_rule_relay_node" FOREIGN KEY ("relay_node_id") REFERENCES "v2_forward_node"("id"),CONSTRAINT "fk_v2_forward_rule_user" FOREIGN KEY ("user_id") REFERENCES "v2_user"("id"));
CREATE TABLE "v2_forward_route" ("id" bigserial,"name" varchar(100) NOT NULL,"priority" bigint DEFAULT 0,"enabled" boolean DEFAULT true,"source_ip" varchar(100),"region" varchar(50),"port_range" varchar(50),"protocol" varchar(20),"relay_group" varchar(50),"exit_group" varchar(50),"relay_node_id" bigint,"exit_node_id" bigint,"balance_mode" varchar(20) DEFAULT 'round-robin',"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_log" ("id" bigserial,"rule_id" bigint,"user_id" bigint,"source_ip" varchar(50),"source_port" bigint,"target_host" varchar(255),"target_port" bigint,"upload" bigint,"download" bigint,"duration" bigint,"relay_node_id" bigint,"exit_node_id" bigint,"status" varchar(20),"error" varchar(500),"created_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_stats" ("id" bigserial,"node_id" bigint,"rule_id" bigint,"user_id" bigint,"date" date,"hour" bigint,"upload" bigint,"download" bigint,"connections" bigint,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_tunnel" ("id" bigserial,"name" varchar(100) NOT NULL,"in_node_id" bigint,"out_node_id" bigint,"in_ip" varchar(255),"out_ip" varchar(255),"in_node_port_sta" bigint,"in_node_port_end" bigint,"type" bigint DEFAULT 1,"flow" bigint DEFAULT 2,"protocol" varchar(30) DEFAULT 'tcp',"traffic_ratio" decimal DEFAULT 1,"interface_name" varchar(255),"tcp_listen_addr" varchar(255) DEFAULT '0.0.0.0',"udp_listen_addr" varchar(255) DEFAULT '0.0.0.0',"status" bigint DEFAULT 1,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_user_tunnel" ("id" bigserial,"user_id" bigint,"tunnel_id" bigint,"flow" bigint DEFAULT 0,"num" bigint DEFAULT 0,"in_flow" bigint DEFAULT 0,"out_flow" bigint DEFAULT 0,"flow_reset_time" bigint DEFAULT 0,"exp_time" bigint DEFAULT 0,"speed_id" bigint,"status" bigint DEFAULT 1,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_forward_user_tunnel_tunnel" FOREIGN KEY ("tunnel_id") REFERENCES "v2_forward_tunnel"("id"),CONSTRAINT "fk_v2_forward_user_tunnel_user" FOREIGN KEY ("user_id") REFERENCES "v2_user"("id"));
CREATE TABLE "v2_forward" ("id" bigserial,"user_id" bigint NOT NULL,"user_name" varchar(255),"name" varchar(100) NOT NULL,"tunnel_id" bigint NOT NULL,"in_port" bigint NOT NULL,"out_port" bigint,"remote_addr" text NOT NULL,"interface_name" varchar(255),"strategy" varchar(20) DEFAULT 'fifo',"status" bigint DEFAULT 1,"runtime_backend" varchar(50) DEFAULT 'gost',"runtime_status" bigint DEFAULT 0,"runtime_message" text,"runtime_last_sync_at" timestamptz,"in_flow" bigint DEFAULT 0,"out_flow" bigint DEFAULT 0,"inx" bigint DEFAULT 0,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_forward_tunnel" FOREIGN KEY ("tunnel_id") REFERENCES "v2_forward_tunnel"("id"),CONSTRAINT "fk_v2_forward_user" FOREIGN KEY ("user_id") REFERENCES "v2_user"("id"));
CREATE TABLE "v2_forward_port_binding" ("id" bigserial,"forward_id" bigint NOT NULL,"node_id" bigint NOT NULL,"transport" varchar(10) NOT NULL,"listen_addr" varchar(255) NOT NULL,"in_port" bigint NOT NULL,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_forward_port_binding_forward" FOREIGN KEY ("forward_id") REFERENCES "v2_forward"("id"));
CREATE TABLE "v2_speed_limit" ("id" bigserial,"created_time" bigint NOT NULL,"updated_time" bigint NOT NULL,"status" bigint DEFAULT 1,"name" varchar(100) NOT NULL,"speed" bigint NOT NULL,"tunnel_id" bigint NOT NULL,"tunnel_name" varchar(100) NOT NULL,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_runtime_job" ("id" bigserial,"backend" varchar(50) NOT NULL,"action" varchar(30) NOT NULL,"resource_type" varchar(30),"resource_id" bigint,"forward_id" bigint,"tunnel_id" bigint,"node_id" bigint,"agent_id" bigint,"status" bigint DEFAULT 0,"payload" text,"result" text,"error" text,"started_at" timestamptz,"claimed_at" timestamptz,"completed_at" timestamptz,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_traffic_cursor" ("id" bigserial,"forward_id" bigint,"backend" varchar(50),"upload_total" bigint DEFAULT 0,"download_total" bigint DEFAULT 0,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_clean_agent" ("id" bigserial,"node_id" bigint,"name" varchar(100) NOT NULL,"token" varchar(160) NOT NULL,"version" varchar(50),"hostname" varchar(255),"os" varchar(50),"arch" varchar(50),"kernel" varchar(120),"public_ip" varchar(64),"private_ip" varchar(64),"capabilities" text,"status" bigint DEFAULT 0,"last_seen" timestamptz,"last_error" text,"revoked_at" timestamptz,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_agent_bridge_task" ("id" bigserial,"task_id" varchar(80),"runtime_job_id" bigint,"node_id" bigint,"forward_id" bigint,"action" varchar(30),"type" varchar(30),"params" text,"status" varchar(20),"dispatched" boolean DEFAULT false,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_forward_latency_bucket" ("id" bigserial,"target_key" varchar(191) NOT NULL,"target_type" varchar(20) NOT NULL,"target_id" bigint,"label" varchar(191),"host" varchar(255),"port" bigint,"bucket_at" timestamptz NOT NULL,"interval_seconds" bigint NOT NULL DEFAULT 60,"sample_count" bigint NOT NULL,"success_count" bigint NOT NULL,"min_rtt" decimal,"avg_rtt" decimal,"max_rtt" decimal,"p95_rtt" decimal,"loss_pct" decimal,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_payment_gateway" ("id" bigserial,"name" varchar(100) NOT NULL,"type" varchar(20) NOT NULL,"enabled" boolean DEFAULT false,"icon" varchar(255),"config" text,"fee_rate" decimal DEFAULT 0,"fee_fixed" decimal DEFAULT 0,"min_amount" decimal DEFAULT 1,"max_amount" decimal DEFAULT 10000,"sort" bigint DEFAULT 0,"description" varchar(500),"total_orders" bigint,"total_amount" decimal,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_payment_record" ("id" bigserial,"trade_no" varchar(64),"gateway_id" bigint,"gateway_type" text,"gateway_trade_no" varchar(100),"provider" varchar(50),"user_id" bigint,"amount" decimal,"fee_amount" decimal,"actual_amount" decimal,"currency" varchar(10) DEFAULT 'CNY',"status" bigint,"paid_at" timestamptz,"cancelled_at" timestamptz,"refunded_at" timestamptz,"notify_data" text,"client_ip" varchar(50),"tx_hash" varchar(255),"wallet_address" varchar(255),"network" varchar(50),"order_id" bigint,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_telegram_bot" ("id" bigserial,"name" varchar(100) NOT NULL,"token" varchar(200) NOT NULL,"enabled" boolean DEFAULT false,"webhook_url" varchar(255),"webhook_set" boolean DEFAULT false,"admin_ids" text,"welcome_msg" text,"allow_bind" boolean DEFAULT true,"allow_sub" boolean DEFAULT true,"allow_ticket" boolean DEFAULT true,"allow_info" boolean DEFAULT true,"total_users" bigint,"total_chats" bigint,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE TABLE "v2_telegram_user" ("id" bigserial,"user_id" bigint,"telegram_id" bigint,"username" varchar(100),"first_name" varchar(100),"last_name" varchar(100),"language_code" varchar(10),"is_banned" boolean DEFAULT false,"banned_at" timestamptz,"notify_expire" boolean DEFAULT true,"notify_traffic" boolean DEFAULT true,"notify_ticket" boolean DEFAULT true,"message_count" bigint,"last_active" timestamptz,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_v2_telegram_user_user" FOREIGN KEY ("user_id") REFERENCES "v2_user"("id"));
CREATE TABLE "v2_telegram_chat" ("id" bigserial,"bot_id" bigint,"telegram_id" bigint,"user_id" bigint,"message_id" bigint,"message_type" varchar(20),"content" text,"reply_to_id" bigint,"created_at" timestamptz,PRIMARY KEY ("id"));
